/* 计算：分频 64，重装载 625，LSI 约 40kHz
   超时 = 64 * (625 + 1) / 40000 = 1.0 秒 */
IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);
IWDG_SetPrescaler(IWDG_Prescaler_64);
IWDG_SetReload(625);
IWDG_ReloadCounter();
IWDG_Enable();

/* 目标：2 秒超时。分频 64 -> 64/40000 = 1.6ms 每计数
   Reload = 2 / 0.0016 - 1 = 1249，取 1250 留点余量 */
IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);
IWDG_SetPrescaler(IWDG_Prescaler_64);
IWDG_SetReload(1250);
IWDG_ReloadCounter();   /* 立即把 RLR 装进计数器 */
IWDG_Enable();

int main(void)
{
  /* 初始化看门狗：1 秒超时 */
  IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);
  IWDG_SetPrescaler(IWDG_Prescaler_64);
  IWDG_SetReload(625);
  IWDG_ReloadCounter();
  IWDG_Enable();

  while (1)
  {
    Task_Run();        /* 所有业务都要在 1 秒内跑完一轮 */
    IWDG_ReloadCounter();   /* 放在循环末尾：能检验整轮是否跑完 */
  }
}

/* 完整初始化：注意顺序，Enable 必须放最后 */
void IWDG_Config(void)
{
  IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);  /* 解锁 */
  IWDG_SetPrescaler(IWDG_Prescaler_64);
  IWDG_SetReload(625);                           /* 1 秒超时 */
  IWDG_ReloadCounter();                          /* 先喂一次，避免刚启动就复位 */
  IWDG_Enable();                                 /* 启动，之后无法关闭 */
}

/* 调试建议：用条件编译，只在正式版本里启动看门狗 */
#ifdef RELEASE
  IWDG_Config();
#endif

/* 严格做法：改完分频等更新完成，再改重装载 */
IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);
IWDG_SetPrescaler(IWDG_Prescaler_64);
while (IWDG_GetFlagStatus(IWDG_FLAG_PVU) != RESET) { }  /* 等分频生效 */

IWDG_SetReload(625);
while (IWDG_GetFlagStatus(IWDG_FLAG_RVU) != RESET) { }  /* 等重装载生效 */

IWDG_ReloadCounter();
IWDG_Enable();
